import{_ as e,o as t,c as o,a2 as l}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"LocalSend 局域網傳輸設定","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/user-guide/settings/localsend.md","filePath":"zh-HK/user-guide/settings/localsend.md","lastUpdated":1785993908000}'),r={name:"zh-HK/user-guide/settings/localsend.md"};function n(s,a,i,d,c,h){return t(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="localsend-局域網傳輸設定" tabindex="-1">LocalSend 局域網傳輸設定 <a class="header-anchor" href="#localsend-局域網傳輸設定" aria-label="Permalink to &quot;LocalSend 局域網傳輸設定&quot;">​</a></h1><p>Lertaro 內建與官方 <a href="https://localsend.org" target="_blank" rel="noreferrer">LocalSend</a> 相容的局域網跨裝置傳輸協定，支援在同一局域網下的手機、電腦裝置之間快速互相傳送檔案、資料夾與純文字。設定頁面路徑為<strong>設定 → LocalSend</strong>。</p><h2 id="基礎設定" tabindex="-1">基礎設定 <a class="header-anchor" href="#基礎設定" aria-label="Permalink to &quot;基礎設定&quot;">​</a></h2><ul><li><strong>啟用 LocalSend 局域網傳輸</strong> —— 開關控制是否開啟 LocalSend 傳輸服務。開啟後系統列選單將提供「傳送至其他裝置...」項目，並可回應全域快捷鍵。</li><li><strong>裝置名稱</strong> —— 本機在局域網中被其他 LocalSend 用戶端識別時顯示的別名。預設根據機器名稱自動生成。</li><li><strong>服務連接埠</strong> —— 監聽局域網傳輸請求的 HTTP/HTTPS 連接埠（預設為 <code>53317</code>）。</li></ul><h2 id="安全與加密" tabindex="-1">安全與加密 <a class="header-anchor" href="#安全與加密" aria-label="Permalink to &quot;安全與加密&quot;">​</a></h2><ul><li><strong>加密傳輸 (HTTPS)</strong> —— 開啟後將使用 HTTPS 加密連線傳輸資料（需要對方裝置也支援加密傳輸）。</li><li><strong>接收 PIN 碼</strong> —— 可設定接收傳輸請求時需驗證的 PIN 碼（留空則不啟用驗證）。</li></ul><h2 id="接收與儲存" tabindex="-1">接收與儲存 <a class="header-anchor" href="#接收與儲存" aria-label="Permalink to &quot;接收與儲存&quot;">​</a></h2><ul><li><strong>自動儲存檔案</strong> —— 開啟後將自動接收並儲存來自信任用戶端的檔案，無需每次手動確認。</li><li><strong>儲存目錄</strong> —— 接收到的檔案預設存放目錄。</li></ul><h2 id="呼出與傳送方式" tabindex="-1">呼出與傳送方式 <a class="header-anchor" href="#呼出與傳送方式" aria-label="Permalink to &quot;呼出與傳送方式&quot;">​</a></h2><ul><li><strong>熱鍵呼出</strong> —— 預設使用 <strong><code>Ctrl+S</code></strong> 快捷鍵（可在<a href="./hotkeys-page.html">熱鍵設定</a>中重新綁定）或點擊系統列選單中的「傳送至其他裝置...」。</li><li><strong>模式切換</strong> —— 傳送視窗提供 [傳送檔案 / 資料夾] 與 [傳送文字] 模式切換，支援實時從搜尋結果中拖曳檔案新增。</li></ul>',10)])])}const _=e(r,[["render",n]]);export{u as __pageData,_ as default};
